from shipping import fee


def test_fee_below_threshold_returns_integer_1000():
    for amount_cents in (0, 500, 9999):
        result = fee(amount_cents)
        assert isinstance(result, int)
        assert result == 1000

from shipping import fee


def test_fee_at_or_above_threshold_returns_integer_zero():
    for amount_cents in (10000, 10001, 20000):
        result = fee(amount_cents)
        assert isinstance(result, int)
        assert result == 0

import pytest
from shipping import fee


def test_fee_rejects_negative_builtin_integers():
    for amount_cents in (-1, -10000):
        with pytest.raises(ValueError):
            fee(amount_cents)

import pytest
from shipping import fee


def test_fee_rejects_non_builtin_integer_argument_types():
    class IntSubclass(int):
        pass

    for amount_cents in (True, 1.0, "1", None, IntSubclass(1)):
        with pytest.raises(TypeError):
            fee(amount_cents)
